WITH filtered_shipments AS (SELECT * FROM shipments WHERE status = 'LOST' OR status IN ('IN_TRANSIT', 'RETURNED', 'DELIVERED')), Summary AS (SELECT CASE WHEN cost >= 76 THEN 'high' WHEN cost >= 39 THEN 'mid' ELSE 'low' END cost_bucket, DATE_FORMAT(shipped_date, 'yyyy-MM') shipped_month, SUM(CASE WHEN carrier = 'UPS' THEN cost ELSE 0 END) ups_cost FROM filtered_shipments GROUP BY CASE WHEN cost >= 76 THEN 'high' WHEN cost >= 39 THEN 'mid' ELSE 'low' END, DATE_FORMAT(shipped_date, 'yyyy-MM')) SELECT * FROM Summary
